   SELECT array_agg(dp.node) INTO frontier FROM pg_temp.pln_depth dp WHERE NOT dp.processed AND dp.remaining_parents=0;
   EXIT WHEN frontier IS NULL;
   UPDATE pg_temp.pln_depth dp SET remaining_parents=dp.remaining_parents-c.n,depth=greatest(dp.depth,c.level)
    FROM(SELECT e.child,count(*)::integer n,max(parent.depth)+1 level FROM pg_temp.pln_edges e JOIN pg_temp.pln_depth parent ON parent.node=e.parent WHERE e.parent=ANY(frontier) GROUP BY e.child)c WHERE dp.node=c.child;
   UPDATE pg_temp.pln_depth SET processed=true WHERE node=ANY(frontier);
